MATCH (:PlantItem {tag: 'EJ-4302A'})-[:is_drawn_on]->(s:Sheet)
RETURN s.sheet_id AS sheet
ORDER BY sheet;

MATCH (a:PlantItem {tag: 'P-2301'}), (b:PlantItem {tag: 'M-2301'})
RETURN EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x.tag <> 'GTV-23002' AND y.tag <> 'GTV-23002')+ (b)
} AS can_flow_without_GTV_23002

MATCH (:PlantItem {tag: 'P-401A'})-[:measured_by]->(instrument:PlantItem)
RETURN instrument.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem:Equipment {tag: 'P-4801A'})-[:line_to*1..]->(v:PlantItem:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-3301B'}), (v:PlantItem:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*0..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (head:ProcessInstrumentationFunction {loop_tag: 'LSHH-11006'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(p:PlantItem {tag: 'P-401A'})
WHERE NOT v:CheckValve
  AND NOT EXISTS { (:ActuatingFunction)-[:control]->(v) }
  AND NOT EXISTS { (:ActuatingElectricalFunction)-[:control]->(v) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (:PlantItem {tag: 'V-4701'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'P-802'}), (b:PlantItem {tag: 'P-902'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((n:PlantItem)-[:line_to]->(m:PlantItem)
                    WHERE n.tag <> 'BFV-9003' AND m.tag <> 'BFV-9003')+ (b)
       } AS reachable **

MATCH (a:PlantItem {tag: 'P-802'}), (b:PlantItem {tag: 'P-902'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((n:PlantItem)-[:line_to]->(m:PlantItem)
                    WHERE n.tag <> 'BFV-9003' AND m.tag <> 'BFV-9003')+ (b)
       } AS reachable

MATCH (a:PlantItem {tag: 'D-501'}), (b:PlantItem {tag: 'P-501'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (v:PlantItem:GateValve {unit_id: '54'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (loop:ProcessInstrumentationFunction {loop_tag: 'PIC-15043'})-[:send_signal_to*]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:BallValve {unit_id: '10'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (loop:ProcessControlFunction {loop_tag: 'LIC-27032'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(e:Equipment {tag: 'E-5201'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'E-4601'}), (b:PlantItem {tag: 'V-4601'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
                    WHERE x.tag <> 'XV-46025' AND y.tag <> 'XV-46025'){1,} (b)
       } AS reachable

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(:PlantItem {tag: 'EA-3901'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'D-1501'}), (b:PlantItem {tag: 'EA-1501'}), (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-2201A'}), (b:PlantItem {tag: 'E-3102'})
RETURN EXISTS {
  MATCH (a) ((n:PlantItem)-[:line_to]->(m:PlantItem) WHERE n.tag <> 'E-2403' AND m.tag <> 'E-2403')+ (b)
} AS can_flow_without_E_2403

MATCH (start:PlantItem {tag: 'D-6001'}), (finish:PlantItem {tag: 'TK-6202'}), (v:Valve)
WHERE EXISTS { (start)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(finish) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag, tag

MATCH (a:PlantItem {tag: 'D-1001'}), (b:PlantItem {tag: 'E-1201'})
RETURN a.tag AS source_tag, b.tag AS target_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (a:PlantItem {tag: 'P-401B'}), (b:PlantItem {tag: 'TK-604'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (s:PlantItem {tag: 'R-5701'}), (t:PlantItem {tag: 'TK-6201'}), (v:Valve)
WHERE EXISTS { (s)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(t) }
RETURN count(DISTINCT v.tag) AS valve_count, collect(DISTINCT v.tag) AS valve_tags

MATCH (a:PlantItem {tag: 'P-801'}), (b:PlantItem {tag: 'V-1501'}), (v:PlantItem:Valve)
WHERE v <> a AND v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (d:PlantItem {tag: 'D-2701'}), (p:PlantItem {tag: 'P-4101A'}), (v:Valve)
WHERE EXISTS { (d)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(p) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'E-2701'}), (b:PlantItem {tag: 'TK-3003'})
RETURN a.tag AS source, b.tag AS destination,
       EXISTS {
         MATCH p = shortestPath((a)-[:line_to*]->(b))
         WHERE ALL(n IN nodes(p) WHERE n.tag <> 'YV-28008')
       } AS reachable

MATCH (a:PlantItem {tag: 'K-6001'}), (b:PlantItem {tag: 'CHV-29004'})
MATCH p = shortestPath((a)-[:line_to*]->(b))
RETURN [n IN nodes(p) | n.tag] AS tags;

MATCH (:PlantItem {tag: 'T-4801'})-[:line_to]->(item:PlantItem)
RETURN DISTINCT item.tag AS tag
ORDER BY tag;

MATCH (loop:ProcessControlFunction {loop_tag: 'LIC-7001'})-[:send_signal_to*1..]->(a:PlantItem {kind: 'actuator'})-[:control]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(target:PlantItem {tag: 'V-4001'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(e:PlantItem {tag: 'EA-4301'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(e:Equipment {tag: 'E-5201'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'TK-2202'})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: 'E-4502'})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id, tag;
